// Spatial bins share the exact BOXES consumed by Rapier and authoritative rays.
const BIN = 4;
const bins = new Map<string, number[]>();
const binKey = (x: number, z: number) => `${x},${z}`;
for (let i = 0; i < BOXES.length; i++) {
  const b = BOXES[i];
  for (let x = Math.floor((b.x - b.w / 2) / BIN); x <= Math.floor((b.x + b.w / 2) / BIN); x++)
    for (let z = Math.floor((b.z - b.d / 2) / BIN); z <= Math.floor((b.z + b.d / 2) / BIN); z++) {
      const key = binKey(x, z);
      const list = bins.get(key) ?? [];
      list.push(i); bins.set(key, list);
    }
}
function nearby(x: number, z: number, pad: number): number[] {
  const ids = new Set<number>();
  for (let xx = Math.floor((x - pad) / BIN); xx <= Math.floor((x + pad) / BIN); xx++)
    for (let zz = Math.floor((z - pad) / BIN); zz <= Math.floor((z + pad) / BIN); zz++)
      for (const i of bins.get(binKey(xx, zz)) ?? []) ids.add(i);
  return [...ids];
}
export function obstructed(x: number, z: number, pad = 0.4, feet = 0, height = 1.85) {
  if (!Number.isFinite(x + z + pad) || x < MAP_BOUNDS.min[0] + pad || x > MAP_BOUNDS.max[0] - pad ||
      z < MAP_BOUNDS.min[2] + pad || z > MAP_BOUNDS.max[2] - pad) return true;
  return nearby(x, z, pad).some(i => {
    const b = BOXES[i];
    if (b.y + b.h / 2 <= feet + 0.22 || b.y - b.h / 2 >= feet + height) return false;
    const dx = Math.max(Math.abs(x - b.x) - b.w / 2, 0);
    const dz = Math.max(Math.abs(z - b.z) - b.d / 2, 0);
    return pad > 0 ? dx * dx + dz * dz < pad * pad - 1e-10 : Math.abs(x-b.x) < b.w/2 && Math.abs(z-b.z) < b.d/2;
  });
}
export function rayBox(ox: number, oy: number, oz: number, dx: number, dy: number, dz: number, b: Box) {
  let near = 0, far = 200;
  for (let axis = 0; axis < 3; axis++) {
    const o = axis === 0 ? ox : axis === 1 ? oy : oz;
    const d = axis === 0 ? dx : axis === 1 ? dy : dz;
    const c = axis === 0 ? b.x : axis === 1 ? b.y : b.z;
    const size = axis === 0 ? b.w : axis === 1 ? b.h : b.d;
    if (Math.abs(d) < 1e-9) { if (o < c - size / 2 || o > c + size / 2) return Infinity; }
    else {
      let a = (c - size / 2 - o) / d, v = (c + size / 2 - o) / d;
      if (a > v) [a, v] = [v, a];
      near = Math.max(near, a); far = Math.min(far, v);
      if (near > far) return Infinity;
    }
  }
  return near;
}
export function wallDistance(x: number, y: number, z: number, dx: number, dy: number, dz: number) {
  if (![x, y, z, dx, dy, dz].every(Number.isFinite) || Math.hypot(dx, dy, dz) < 1e-9) return Infinity;
  let bx = Math.floor(x / BIN), bz = Math.floor(z / BIN), nearest = Infinity;
  const sx = Math.sign(dx), sz = Math.sign(dz);
  const deltaX = Math.abs(dx) > 1e-9 ? BIN / Math.abs(dx) : Infinity;
  const deltaZ = Math.abs(dz) > 1e-9 ? BIN / Math.abs(dz) : Infinity;
  let tx = sx ? ((bx + (sx > 0 ? 1 : 0)) * BIN - x) / dx : Infinity;
  let tz = sz ? ((bz + (sz > 0 ? 1 : 0)) * BIN - z) / dz : Infinity;
  const seen = new Set<number>();
  for (let step = 0; step < 2048; step++) {
    for (const i of bins.get(binKey(bx, bz)) ?? []) if (!seen.has(i)) {
      seen.add(i); nearest = Math.min(nearest, rayBox(x, y, z, dx, dy, dz, BOXES[i]));
    }
    const next = Math.min(tx, tz);
    if (next > 200 || next > nearest || !Number.isFinite(next)) break;
    if (tx <= tz) { bx += sx; tx += deltaX; }
    else { bz += sz; tz += deltaZ; }
  }
  return nearest;
}
export function sight(a: { x: number; y?: number; z: number }, b: { x: number; y?: number; z: number }) {
  const dx = b.x - a.x, dy = (b.y ?? 1.4) - (a.y ?? 1.4), dz = b.z - a.z;
  const length = Math.hypot(dx, dy, dz);
  return length < 1e-9 || wallDistance(a.x, a.y ?? 1.4, a.z, dx / length, dy / length, dz / length) > length - 0.2;
}
export function isInsideSite(site: typeof SITES[number], x: number, z: number, y = 0) {
  return x >= site.min[0] && x <= site.max[0] && z >= site.min[2] && z <= site.max[2] && y >= site.min[1] - 0.05 && y <= site.max[1];
}

// Ground routes deliberately do not claim terrace navigation. Source reachable cells
// are intersected with the live capsule clearance and edge tests from these BOXES.
const nav = new Uint8Array(NAV.columns * NAV.rows);
const point = (k: number) => ({x: NAV.origin[0] + (k % NAV.columns) * NAV.resolution,
  z: NAV.origin[2] + Math.floor(k / NAV.columns) * NAV.resolution});
for (const [row, begin, end] of NAV.runs) for (let col = begin; col < end; col++) {
  const k = row * NAV.columns + col, p = point(k);
  if (!obstructed(p.x, p.z, 0.5)) nav[k] = 1;
}
const edges = new Uint8Array(nav.length);
const offsets = [1, -1, NAV.columns, -NAV.columns];
for (let k = 0; k < nav.length; k++) if (nav[k]) {
  const a = point(k);
  for (let dir = 0; dir < 4; dir++) {
    const n = k + offsets[dir];
    if (!nav[n] || (dir < 2 && Math.floor(k / NAV.columns) !== Math.floor(n / NAV.columns))) continue;
    const b = point(n);
    if ([0.25, 0.5, 0.75].every(t => !obstructed(a.x + (b.x - a.x) * t, a.z + (b.z - a.z) * t, 0.5))) edges[k] |= 1 << dir;
  }
}
function nearestCell(x: number, z: number) {
  let best = -1, distance = Infinity;
  // Bounded map: snapping off-grid endpoints does not fabricate passable cells.
  for (let k = 0; k < nav.length; k++) if (nav[k]) {
    const p = point(k), d = (x-p.x)**2 + (z-p.z)**2;
    if (d < distance) { distance = d; best = k; }
  }
  return best;
}
const fields = new Map<number, Int32Array>();
function field(goal: number) {
  let distances = fields.get(goal);
  if (distances) return distances;
  distances = new Int32Array(nav.length).fill(-1);
  const queue = new Int32Array(nav.length); let head = 0, tail = 1;
  queue[0] = goal; distances[goal] = 0;
  while (head < tail) {
    const k = queue[head++];
    for (let dir = 0; dir < 4; dir++) if (edges[k] & (1 << dir)) {
      const n = k + offsets[dir];
      if (distances[n] < 0) { distances[n] = distances[k] + 1; queue[tail++] = n; }
    }
  }
  if (fields.size >= 24) fields.delete(fields.keys().next().value!);
  fields.set(goal, distances); return distances;
}
export function pathfind(sx: number, sz: number, tx: number, tz: number): {x: number; z: number}[] {
  if (![sx,sz,tx,tz].every(Number.isFinite)) return [];
  const start = nearestCell(sx, sz), goal = nearestCell(tx, tz);
  if (start < 0 || goal < 0) return [];
  const distances = field(goal);
  if (distances[start] < 0) return [];
  const cells = [start]; let current = start;
  while (current !== goal && cells.length <= nav.length) {
    let next = -1;
    for (let dir = 0; dir < 4; dir++) if (edges[current] & (1 << dir)) {
      const n = current + offsets[dir];
      if (distances[n] === distances[current] - 1) { next = n; break; }
    }
    if (next < 0) return [];
    cells.push(next); current = next;
  }
  const result: {x: number;z: number}[] = [];
  if (Math.hypot(point(start).x-sx, point(start).z-sz) > 0.2) result.push(point(start));
  // Preserve every turn, compress only exactly straight sequences. Physics remains authoritative.
  for (let i = 1; i < cells.length; i++)
    if (i === cells.length - 1 || cells[i] - cells[i-1] !== cells[i+1] - cells[i]) result.push(point(cells[i]));
  return result;
}
export const NAV_STATS = { cellCount: nav.reduce((a,b) => a+b, 0), resolution: NAV.resolution, capsuleClearance: 0.5, groundOnly: true };

export const NAV_GRID = {origin: NAV.origin, columns: NAV.columns, rows: NAV.rows, resolution: NAV.resolution,
  standingHeight: 1.85, clearance: 0.5,
  isWalkable(col: number, row: number) {
    return Number.isInteger(col) && Number.isInteger(row) && col >= 0 && col < NAV.columns && row >= 0 && row < NAV.rows && nav[row*NAV.columns+col] === 1;
  },
};
